.lab-bench {
  --ink: #2d3748;
  --muted: #718096;
  --accent: #3182ce;
  --warm: #dd6b20;
  --line: #e2e8f0;
  --paper: #f7fafc;

  font-family: system-ui, -apple-system, sans-serif;
  color: var(--ink);
  line-height: 1.6;
  padding: 2rem 1rem;
  max-width: 900px;
  margin: 0 auto;
  background: var(--paper);
}

.section-header h1 {
  font-size: 2rem;
  margin-bottom: 0.5rem;
  color: var(--ink);
}

.lead {
  font-size: 1.125rem;
  color: var(--muted);
  margin-bottom: 2rem;
}

.dual-channel {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.5rem;
  margin: 2rem 0;
}

.channel {
  background: rgba(255,255,255,0.7);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 1rem;
  backdrop-filter: blur(4px);
}

.channel-label {
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: 0.5rem;
  color: var(--muted);
}

.parametric .channel-label { color: var(--accent); }
.non-parametric .channel-label { color: var(--warm); }

.visual-block svg {
  display: block;
  width: 100%;
  height: auto;
}

.content-block {
  margin: 2rem 0;
  padding: 1.5rem;
  background: white;
  border-left: 4px solid var(--accent);
  border-radius: 0 8px 8px 0;
}

.content-block h2 {
  font-size: 1.5rem;
  margin-top: 0;
}

.content-block p {
  margin: 1rem 0;
  font-size: 1rem;
}

.source-links {
  margin-top: 1.5rem;
}

.source-btn {
  background: transparent;
  border: 1px solid var(--line);
  color: var(--muted);
  padding: 0.25rem 0.75rem;
  border-radius: 4px;
  font-size: 0.875rem;
  cursor: pointer;
  margin-right: 0.5rem;
  transition: all 0.2s;
}

.source-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.interaction-area {
  margin: 2rem 0;
  padding: 1.5rem;
  background: white;
  border: 1px solid var(--line);
  border-radius: 8px;
}

.interaction-area h3 {
  margin-top: 0;
  font-size: 1.25rem;
}

.instruction {
  font-size: 0.875rem;
  color: var(--muted);
  margin-bottom: 1rem;
}

.table-container {
  overflow-x: auto;
  margin: 1rem 0;
}

#qa-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9rem;
}

#qa-table th,
#qa-table td {
  padding: 0.75rem;
  text-align: left;
  border-bottom: 1px solid var(--line);
}

#qa-table th {
  background: var(--paper);
  font-weight: 600;
  color: var(--muted);
}

#qa-table tbody tr {
  cursor: pointer;
  transition: background 0.2s;
}

#qa-table tbody tr:hover {
  background: rgba(49, 130, 206, 0.05);
}

#qa-table tbody tr.highlight-rag {
  background: rgba(49, 130, 206, 0.1);
  border-left: 3px solid var(--accent);
}

#qa-table tbody tr.highlight-dpr {
  background: rgba(221, 107, 32, 0.1);
  border-left: 3px solid var(--warm);
}

.highlight-panel {
  margin-top: 1.5rem;
  padding: 1rem;
  background: var(--paper);
  border-radius: 6px;
}

.highlight-panel h4 {
  margin-top: 0;
  font-size: 1rem;
  color: var(--ink);
}

.stat-comparison {
  margin: 1rem 0;
}

.stat-item {
  margin-bottom: 1rem;
}

.stat-label {
  display: block;
  font-size: 0.875rem;
  color: var(--muted);
  margin-bottom: 0.25rem;
}

.stat-bar-container {
  position: relative;
  height: 24px;
  background: var(--line);
  border-radius: 4px;
  overflow: hidden;
}

.stat-bar {
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding-right: 0.5rem;
  color: white;
  font-size: 0.75rem;
  font-weight: 600;
  transition: width 0.3s ease;
}

.rag-bar {
  background: var(--accent);
}

.extractive-bar {
  background: var(--muted);
}

.stat-value {
  position: absolute;
  right: 0.5rem;
  top: 50%;
  transform: translateY(-50%);
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--ink);
}

.insight {
  font-size: 0.875rem;
  color: var(--muted);
  font-style: italic;
}

.claims-section {
  margin-top: 2rem;
}

.claims-section h3 {
  font-size: 1.25rem;
  margin-bottom: 1rem;
}

.claim-list {
  list-style: none;
  padding: 0;
}

.claim-item {
  padding: 1rem;
  margin-bottom: 1rem;
  background: white;
  border: 1px solid var(--line);
  border-radius: 6px;
  font-size: 0.9rem;
}

.claim-item strong {
  color: var(--accent);
  display: block;
  margin-bottom: 0.5rem;
}

@media (max-width: 600px) {
  .dual-channel {
    grid-template-columns: 1fr;
  }

  .lab-bench {
    padding: 1rem;
  }

  .content-block, .interaction-area {
    padding: 1rem;
  }
}

