(function() {
  'use strict';

  // Initialize from runtime data
  const tables = window.paperMindData?.tables || [];
  const table1 = tables.find(t => t.id === 'p6-Table_1');

  if (!table1) {
    console.warn('Table 1 not found in runtime data');
    return;
  }

  // Populate table
  const tableBody = document.querySelector('#qa-table tbody');
  if (!tableBody) return;

  tableBody.innerHTML = '';

  table1.rows.forEach(row => {
    const tr = document.createElement('tr');
    tr.dataset.model = row.values.Model;

    // Add cells
    ['Model', 'NQ', 'TQA', 'WQ', 'CT'].forEach(col => {
      const td = document.createElement('td');
      td.textContent = row.values[col] || '-';
      tr.appendChild(td);
    });

    // Add hover effects for RAG and DPR rows
    if (row.values.Model.includes('RAG')) {
      tr.classList.add('rag-row');
      tr.addEventListener('mouseenter', () => {
        document.querySelectorAll('.rag-row').forEach(r => r.classList.add('highlight-rag'));
        document.querySelectorAll('.dpr-row').forEach(r => r.classList.remove('highlight-dpr'));
      });
      tr.addEventListener('mouseleave', () => {
        document.querySelectorAll('.rag-row').forEach(r => r.classList.remove('highlight-rag'));
      });
    } else if (row.values.Model.includes('DPR')) {
      tr.classList.add('dpr-row');
      tr.addEventListener('mouseenter', () => {
        document.querySelectorAll('.dpr-row').forEach(r => r.classList.add('highlight-dpr'));
        document.querySelectorAll('.rag-row').forEach(r => r.classList.remove('highlight-rag'));
      });
      tr.addEventListener('mouseleave', () => {
        document.querySelectorAll('.dpr-row').forEach(r => r.classList.remove('highlight-dpr'));
      });
    }

    tableBody.appendChild(tr);
  });

  // Source button handlers
  document.querySelectorAll('.source-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
      const sourceId = e.target.dataset.source;
      if (window.paperMindData?.sources?.[sourceId]) {
        // In real implementation, this would trigger source modal
        const source = window.paperMindData.sources[sourceId];
        console.log('Source requested:', source);
      }
    });
  });

  // Claim verification handlers
  document.querySelectorAll('.claim-item').forEach(item => {
    item.addEventListener('click', (e) => {
      if (e.target.classList.contains('source-btn')) return;
      const claimId = item.dataset.claim;
      console.log('Claim verified:', claimId);
    });
  });

  // Reset functionality
  const resetBtn = document.createElement('button');
  resetBtn.type = 'button';
  resetBtn.textContent = '复位';
  resetBtn.className = 'source-btn';
  resetBtn.style.marginTop = '1rem';
  resetBtn.addEventListener('click', () => {
    document.querySelectorAll('.highlight-rag, .highlight-dpr').forEach(el => {
      el.classList.remove('highlight-rag', 'highlight-dpr');
    });
  });

  const interactionArea = document.querySelector('.interaction-area');
  if (interactionArea) {
    interactionArea.appendChild(resetBtn);
  }

  // Keyboard accessibility
  document.querySelectorAll('#qa-table tbody tr').forEach(row => {
    row.setAttribute('tabindex', '0');
    row.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        row.click();
      }
    });
  });

  // Respect reduced motion
  const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (prefersReducedMotion) {
    document.querySelectorAll('.stat-bar').forEach(bar => {
      bar.style.transition = 'none';
    });
  }
})();
